globalThis.b=nodes.open({task:"Is demand for grid equipment from Caldrian data centres rising through 2027?"});
const [x,y]=await Promise.all([a.result(),b.result()]);
return [x.line,await read(x.ref),y.line,await read(y.ref)];

// children already opened: demand, financing, pricing. Wait for them.
const out=[];const done=new Set();
while(done.size<3){const r=await nodes.next();for(const l of r.lines){out.push(l);if(/^n[234]\.r\d/.test(l))done.add(l.slice(0,2));}}
